import { c } from 'ttag';

import {
    createPaymentToken,
    getCreatePaymentToken,
    getDefaultVerifyPayment,
    process,
} from '@proton/components/containers/payments/paymentTokenHelper';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';

const { STATUS_CHARGEABLE, STATUS_PENDING, STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } = PAYMENT_TOKEN_STATUS;

let tab: { closed: boolean; close: jest.Mock };

beforeEach(() => {
    jest.clearAllMocks();
    jest.useFakeTimers();
    tab = { closed: false, close: jest.fn() };
    jest.spyOn(window, 'open').mockReturnValue(tab as any);
    jest.spyOn(window, 'removeEventListener');
    jest.spyOn(window, 'addEventListener');
});

afterEach(() => {
    jest.useRealTimers();
    jest.restoreAllMocks();
});

describe('process', () => {
    const params = { ApprovalURL: 'https://example.proton.me', ReturnHost: 'return.proton.me', Token: 'token' };

    it('opens the approval page and resolves when it closes', async () => {
        const api = jest.fn();
        const promise = process({ ...params, api, signal: new AbortController().signal }, 10);
        expect(window.open).toHaveBeenCalledWith(params.ApprovalURL);
        tab.closed = true;
        await jest.advanceTimersByTimeAsync(10);
        await expect(promise).resolves.toBeUndefined();
        expect(api).not.toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves on external abort and clears timers and listeners', async () => {
        const controller = new AbortController();
        const api = jest.fn();
        const promise = process({ ...params, api, signal: controller.signal }, 10);
        controller.abort();
        await expect(promise).resolves.toBeUndefined();
        expect(tab.close).toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
        expect(window.removeEventListener).toHaveBeenCalledWith('message', expect.any(Function), false);
        expect(api).not.toHaveBeenCalled();
    });

    it('polls at the configured interval after the approval message and stops at a terminal status', async () => {
        const api = jest.fn().mockResolvedValueOnce({ Status: STATUS_PENDING }).mockResolvedValueOnce({ Status: STATUS_CHARGEABLE });
        const promise = process({ ...params, api, signal: new AbortController().signal }, 10, 25);
        window.dispatchEvent(new MessageEvent('message', { origin: 'https://return.proton.me', data: {} }));
        await Promise.resolve();
        expect(api).toHaveBeenCalledTimes(1);
        await jest.advanceTimersByTimeAsync(24);
        expect(api).toHaveBeenCalledTimes(1);
        await jest.advanceTimersByTimeAsync(1);
        await expect(promise).resolves.toBeUndefined();
        expect(api).toHaveBeenCalledTimes(2);
        expect(jest.getTimerCount()).toBe(0);
    });

    it.each([STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED])('resolves at terminal status %s', async (Status) => {
        const api = jest.fn().mockResolvedValue({ Status });
        const promise = process({ ...params, api, signal: new AbortController().signal });
        window.dispatchEvent(new MessageEvent('message', { origin: 'https://return.proton.me', data: {} }));
        await expect(promise).resolves.toBeUndefined();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves when the approval page sends cancellation', async () => {
        const api = jest.fn();
        const promise = process({ ...params, api, signal: new AbortController().signal });
        window.dispatchEvent(new MessageEvent('message', { origin: 'https://return.proton.me', data: { cancel: '1' } }));
        await expect(promise).resolves.toBeUndefined();
        expect(api).not.toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });
});

describe('createPaymentToken', () => {
    const params = { PaymentMethodID: 'saved-card' };
    const verified = { Payment: { Type: 'token', Details: { Token: '[REDACTED_SECRET]' } } } as any;

    it('returns a chargeable token without invoking verify', async () => {
        const api = jest.fn().mockResolvedValue({ Token: 'ready', Status: STATUS_CHARGEABLE });
        const verify = jest.fn();
        const result = await createPaymentToken({ params, api, verify });
        expect(result.Payment.Details.Token).toBe('ready');
        expect(verify).not.toHaveBeenCalled();
    });

    it('passes pending token details to the injected verifier', async () => {
        const api = jest.fn().mockResolvedValue({ Token: 'pending', Status: STATUS_PENDING, ApprovalURL: 'url', ReturnHost: 'host' });
        const verify = jest.fn().mockResolvedValue(verified);
        const create = getCreatePaymentToken(verify);
        await expect(create({ params, api, mode: 'add-card' })).resolves.toBe(verified);
        expect(verify).toHaveBeenCalledWith({ mode: 'add-card', Payment: undefined, Token: 'pending', ApprovalURL: 'url', ReturnHost: 'host' });
    });

    it.each([STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED])('rejects initial terminal status %s', async (Status) => {
        const api = jest.fn().mockResolvedValue({ Token: 'failed', Status });
        const verify = jest.fn();
        await expect(createPaymentToken({ params, api, verify })).rejects.toThrow();
        expect(verify).not.toHaveBeenCalled();
    });
});

describe('getDefaultVerifyPayment', () => {
    it('creates a verification modal with its own process controller', async () => {
        const createModal = jest.fn();
        const api = jest.fn();
        const verify = getDefaultVerifyPayment(createModal, api);
        const promise = verify({ Token: 'pending', ApprovalURL: 'url', ReturnHost: 'host', mode: 'add-card' });
        const modal = createModal.mock.calls[0][0];
        expect(modal.props).toMatchObject({ token: 'pending', mode: 'add-card', payment: undefined });
        const { abort, promise: processPromise } = modal.props.onProcess();
        expect(abort).toBeInstanceOf(AbortController);
        abort.abort();
        await expect(processPromise).resolves.toBeUndefined();
        const result = { Payment: { Type: 'token', Details: { Token: 'pending' } } };
        modal.props.onSubmit(result);
        await expect(promise).resolves.toBe(result);
    });
});
