it('should abort the promise and call onClose if user cancels', async () => {
    const processingDelay = 100;
    const { getByText } = render(<ContextPaymentVerificationModal {...props} processingDelay={processingDelay} />);

    getByText('Verify').click();

    await wait(processingDelay);

    getByText('Cancel').click();

    await waitFor(() => expect(props.onClose).toHaveBeenCalledTimes(1));
    expect(promiseWithController.abort.abort).toHaveBeenCalledTimes(1);
});

    return new Promise<boolean>((resolve, reject) => {
        let settled = false;
        let processing = false;
        let listeningTimer: ReturnType<typeof setTimeout> | undefined;
        let pollingTimer: ReturnType<typeof setTimeout> | undefined;

        const cleanup = () => {
            clearTimeout(listeningTimer);
            clearTimeout(pollingTimer);
            window.removeEventListener('message', onMessage, false);
            signal.removeEventListener('abort', abort);
            tab?.close();
        };

        const finish = (verified: boolean, error?: Error) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            if (error) {
                reject(error);
            } else {
                resolve(verified);
            }
        };

        const poll = async () => {
            if (settled || signal.aborted) {
                finish(false);
                return;
            }
            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (settled) {
                    return;
                }
                if (Status === STATUS_PENDING) {
                    pollingTimer = setTimeout(poll, delayPolling);
                } else if (
                    Status === STATUS_CHARGEABLE ||
                    Status === STATUS_FAILED ||
                    Status === STATUS_CONSUMED ||
                    Status === STATUS_NOT_SUPPORTED
                ) {
                    finish(Status === STATUS_CHARGEABLE);
                } else {
                    finish(false, new Error(c('Error').t`Unknown payment token status`));
                }
            } catch (error: any) {
                if (signal.aborted) {
                    finish(false);
                } else {
                    finish(false, error);
                }
            }
        };

        const listenTab = () => {
            if (settled) {
                return;
            }
            if (tab?.closed) {
                finish(false);
                return;
            }
            listeningTimer = setTimeout(listenTab, delayListening);
        };

        const onMessage = (event: MessageEvent) => {
            if (settled || processing || getHostname(event.origin) !== ReturnHost) {
                return;
            }

            if (event.data?.cancel === '1') {
                finish(false);
                return;
            }
            processing = true;
            clearTimeout(listeningTimer);
            tab?.close();
            poll();
        };

        const abort = () => {
            finish(false);
        };

        signal.addEventListener('abort', abort);
        window.addEventListener('message', onMessage, false);
        if (signal.aborted) {
            finish(false);
            return;
        }
        listenTab();
    });
};

